class Dev:
    def __init__(s, ip):
        s.ip, s.cj, s.base = ip, http.cookiejar.CookieJar(), None
        s.op = urllib.request.build_opener(
            urllib.request.HTTPCookieProcessor(s.cj), urllib.request.HTTPSHandler(context=ctx))

    def req(s, path, data=None, headers=None, t=15):
        r = urllib.request.Request(s.base + path, data=data, headers=headers or {})
        with s.op.open(r, timeout=t) as f:
            return f.read().decode('utf-8', 'replace'), f

    def connect(s):
        for sch in ('http', 'https'):
            s.base = f'{sch}://{s.ip}'
            try:
                body, f = s.op.open(s.base + '/', timeout=8), None
                f = body
                txt = f.read().decode('utf-8', 'replace') + str(f.headers)
                m = re.match(r'(https?://[^/]+)', f.geturl())
                s.base = m.group(1) if m else s.base
                return (txt + f.geturl()).lower()
            except urllib.error.HTTPError as e:
                return (e.read().decode('utf-8', 'replace') + str(e.headers)).lower()
            except Exception:
                continue
        raise Exception('تعذر الاتصال بالأكسس (المنفذ 80 أو 443)')


def kind(page):
    if 'luci' in page or 'openwrt' in page: return 'openwrt'
    if any(k in page for k in ('airos', 'ubiquiti', 'ubnt', 'login.cgi')): return 'airos'
    if any(k in page for k in ('tp-link', 'tplink', 'pharos')): return 'tplink'
    return None


class Fail(Exception):
    def __init__(s, msg, log=None):
        super().__init__(msg)
        s.log = log or []


def ubus(d, sid, obj, m, args):
    body = json.dumps({"jsonrpc": "2.0", "id": 1, "method": "call", "params": [sid, obj, m, args]}).encode()
    txt, _ = d.req('/ubus', body, {'Content-Type': 'application/json'}, t=40)
    j = json.loads(txt)
    r = j.get('result')
    if not r:
        e = j.get('error') or {}
        raise Exception(f"{obj}.{m} رفض: {e.get('message') or txt[:80]}" + (f" (رمز {e['code']})" if 'code' in e else ''))
    if r[0] != 0:
        raise Exception(f'{obj}.{m} رجّع الرمز {r[0]}' + (' (رفض الصلاحية)' if r[0] == 6 else ''))
    return r[1] if len(r) > 1 else {}


def direct_sid(d, u, p):
    return ubus(d, '0' * 32, 'session', 'login', {'username': u, 'password': p, 'timeout': 300})['ubus_rpc_session']


def luci_sid(d, u, p):
    data = urllib.parse.urlencode({'luci_username': u, 'luci_password': p}).encode()
    try:
        d.req('/cgi-bin/luci/', data, {'Content-Type': 'application/x-www-form-urlencoded'})
    except urllib.error.HTTPError as e:
        if e.code not in (302, 303): raise Exception(f'LuCI رجّع HTTP {e.code}')
    for c in d.cj:
        if c.name.startswith('sysauth') and c.value: return c.value
    raise Exception('LuCI لم يرجّع جلسة')


def ubus_scan(d, sid):
    devs = []
    try:
        devs = ubus(d, sid, 'iwinfo', 'devices', {}).get('devices', [])
    except Exception:
        pass
    if not devs:
        try:
            for rv in ubus(d, sid, 'network.wireless', 'status', {}).values():
                if isinstance(rv, dict):
                    devs += [i['ifname'] for i in rv.get('interfaces', []) if i.get('ifname')]
        except Exception:
            pass
    devs = devs or ['wlan0', 'wlan1']
    info = {}
    for dv in devs:
        try:
            info[dv] = ubus(d, sid, 'iwinfo', 'info', {'device': dv})
        except Exception:
            info[dv] = {}
    last = None
    for dv in sorted(devs, key=lambda x: not (2400 <= (info[x].get('frequency') or 0) <= 2500)):
        try:
            res = ubus(d, sid, 'iwinfo', 'scan', {'device': dv}).get('results', [])
            nets = [{'ssid': r.get('ssid', ''), 'bssid': r.get('bssid', ''),
                     'channel': r.get('channel'), 'signal': r.get('signal')} for r in res]
            return dv, info[dv].get('channel'), nets
        except Exception as e:
            last = e
    raise last or Exception('لا توجد واجهة لاسلكية في الجهاز')


def pk_exec(ip, u, p, cmd, t=40):
    try: import paramiko
    except ImportError: raise Exception('ssh غير مثبت: pkg install -y openssh')
    c = paramiko.SSHClient()
    c.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    try:
        c.connect(ip, username=u, password=p, timeout=8, banner_timeout=15, auth_timeout=15, look_for_keys=False, allow_agent=False)
        _, o, e = c.exec_command(cmd, timeout=t)
        out = o.read().decode('utf-8', 'replace')
        err = e.read().decode('utf-8', 'replace')
        rc = o.channel.recv_exit_status()
    finally:
        c.close()
    if rc: raise Exception(f'ssh رجّع {rc}: ' + err.strip()[-120:])
    return out


def ssh_scan(d, u, p):
    ssh = shutil.which('ssh')
    if not ssh:
        sh = lambda cmd, t=40: pk_exec(d.ip, u, p, cmd, t)
        devs = re.findall(r'^(\S+)\s+ESSID', sh('iwinfo'), re.M)
        if not devs: raise Exception('لا توجد واجهة لاسلكية في الجهاز')
        pick, cur = devs[0], None
        for dv in devs:
            m = re.search(r'Channel:\s*(\d+)', sh(f'iwinfo {dv} info'))
            if m and 1 <= int(m.group(1)) <= 14:
                pick, cur = dv, int(m.group(1)); break
        return pick, cur, parse_iwinfo_scan(sh(f'iwinfo {pick} scan', 60))
    if not re.fullmatch(r'[A-Za-z0-9_][A-Za-z0-9_.-]*', u or ''): raise Exception('اسم مستخدم غير صالح لـ SSH')
    import tempfile
    fd, ap = tempfile.mkstemp(prefix='qx', suffix='.sh')
    os.write(fd, f"#!{shutil.which('sh') or '/bin/sh'}\necho \"$QX_PW\"\n".encode())
    os.close(fd)
    os.chmod(ap, 0o700)
    env = dict(os.environ, QX_PW=p, SSH_ASKPASS=ap, SSH_ASKPASS_REQUIRE='force', DISPLAY=os.environ.get('DISPLAY') or ':0')

    def sh(cmd, t=40):
        r = subprocess.run([ssh, '-o', 'StrictHostKeyChecking=no', '-o', 'UserKnownHostsFile=/dev/null',
                            '-o', 'ConnectTimeout=8', '-o', 'NumberOfPasswordPrompts=1',
                            '-o', 'PreferredAuthentications=password,keyboard-interactive',
                            f'{u}@{d.ip}', cmd], capture_output=True, text=True, timeout=t, env=env, stdin=subprocess.DEVNULL)
        if r.returncode: raise Exception(f'ssh رجّع {r.returncode}: ' + r.stderr.strip()[-120:])
        return r.stdout
    try:
        devs = re.findall(r'^(\S+)\s+ESSID', sh('iwinfo'), re.M)
        if not devs: raise Exception('لا توجد واجهة لاسلكية في الجهاز')
        pick, cur = devs[0], None
        for dv in devs:
            m = re.search(r'Channel:\s*(\d+)', sh(f'iwinfo {dv} info'))
            if m and 1 <= int(m.group(1)) <= 14:
                pick, cur = dv, int(m.group(1)); break
        return pick, cur, parse_iwinfo_scan(sh(f'iwinfo {pick} scan', 60))
    finally:
        try: os.remove(ap)
        except OSError: pass


def parse_iwinfo_scan(txt):
    nets = []
    for cell in txt.split('Cell ')[1:]:
        g = lambda rx: (re.search(rx, cell) or [None, None])[1]
        ch, sg = g(r'Channel:\s*(\d+)'), g(r'Signal:\s*(-?\d+)')
        nets.append({'ssid': g(r'ESSID:\s*"(.*)"') or '', 'bssid': g(r'Address:\s*([0-9A-Fa-f:]{17})') or '',
                     'channel': int(ch) if ch else None, 'signal': int(sg) if sg else None})
    return nets


def scan_openwrt(d, u, p, log):
    for name, fn in (('الجلسة المباشرة', direct_sid), ('جلسة LuCI', luci_sid), ('SSH', None)):
        try:
            if fn:
                sid = fn(d, u, p)
                log.append(f'{name}: تم الدخول')
                pick, cur, nets = ubus_scan(d, sid)
            else:
                pick, cur, nets = ssh_scan(d, u, p)
            log.append(f'✓ {name}: نجح الفحص ({len(nets)} شبكة)')
            return {'model': 'OpenWrt (' + pick + ')', 'channel': cur, 'nets': nets}
        except Exception as e:
            log.append(f'✗ {name}: {e}')
    raise Fail('فشلت كل الطرق. راجع سجل الخطوات', log)


def f2ch(f):
    try:
        v = float(f)
        return round(((v * 1000 if v < 100 else v) - 2407) / 5)
    except Exception: return None


def num(v):
    try: return float(re.sub(r'[^0-9.\-]', '', str(v)))
    except Exception: return None


def scan_airos(d, u, p, log):
    b = '----x' + uuid.uuid4().hex
    body = ''.join(f'--{b}\r\nContent-Disposition: form-data; name="{k}"\r\n\r\n{v}\r\n'
                   for k, v in (('uri', '/'), ('username', u), ('password', p))) + f'--{b}--\r\n'
    d.req('/login.cgi', body.encode(), {'Content-Type': 'multipart/form-data; boundary=' + b})
    try:
        st = json.loads(d.req('/status.cgi')[0])
    except Exception:
        raise Exception('فشل الدخول: تأكد من اسم المستخدم وكلمة السر')
    w = st.get('wireless', {})
    cur = w.get('channel') or f2ch(re.sub(r'\D', '', str(w.get('frequency', '')))[:4])
    model = st.get('host', {}).get('devmodel', 'airOS')
    try:
        data = json.loads(d.req('/survey.json.cgi?iface=ath0', t=45)[0])
    except Exception:
        raise Exception('تم الدخول لكن تعذر قراءة الفحص من هذا الإصدار من airOS')
    nets = []
    log.append('airOS: نوع البيانات ' + type(data).__name__)
    if isinstance(data, list) and data and isinstance(data[0], dict):
        log.append('airOS عينة: ' + json.dumps(data[0], ensure_ascii=False)[:300])
    for n in data if isinstance(data, list) else []:
        if not isinstance(n, dict): continue
        sig = next((num(n[k]) for k in ('signal', 'signal_level', 'level', 'signal_dbm', 'signalStrength') if n.get(k) is not None), None)
        if sig is None and n.get('rssi') is not None and num(n['rssi']) is not None: sig = num(n['rssi']) - 95
        ch = num(n.get('channel'))
        ch = int(ch) if ch else f2ch(n.get('frequency'))
        nets.append({'ssid': n.get('essid') or n.get('ssid') or '', 'bssid': n.get('mac') or n.get('bssid') or '',
                     'channel': ch, 'signal': sig})
    return {'model': model + ' (airOS)', 'channel': cur, 'nets': nets}


def analyze(nets):
    sc = {c: 0.0 for c in range(1, 12)}
    for n in nets:
        try: ch, s = int(n['channel']), float(n['signal'])
        except Exception: continue
        if not 1 <= ch <= 14: continue
        w = 10 ** ((s + 100) / 10)
        for c in sc:
            dd = abs(c - ch)
            if dd < 5: sc[c] += w * (1 - dd / 5)
    return sc, min((1, 6, 11), key=lambda c: sc[c])


def run(q):
    log = []
    try:
        ip = str(q.get('ip', '')).strip()
        if not re.fullmatch(r'\d{1,3}(\.\d{1,3}){3}', ip): raise Exception('أدخل عنوان IP واحداً فقط، مثال 192.168.10.5')
        ipaddress.IPv4Address(ip)
        d = Dev(ip)
        k = kind(d.connect())
        log.append(f'النوع المكتشف: {k}')
        u, p = q.get('user', ''), q.get('pw', '')
        if k == 'openwrt': r = scan_openwrt(d, u, p, log)
        elif k == 'airos': r = scan_airos(d, u, p, log)
        elif k == 'tplink': raise Exception('تم التعرف على TP-Link، لكنه غير مدعوم في هذه النسخة بعد')
        else: raise Exception('لم أتعرف على نوع الأكسس من صفحته')
        if not any(isinstance(n.get('signal'), (int, float)) and isinstance(n.get('channel'), (int, float)) for n in r['nets']):
            raise Fail('الفحص رجع بلا قوة إشارة أو قنوات صالحة، لا يمكن اقتراح قناة. راجع السجل', log)
        r['scores'], r['best'] = analyze(r['nets'])
        r['log'] = log
        return r
    except Fail:
        raise
    except Exception as e:
        raise Fail(str(e), log)


def ssh_run(d, u, p, cmd, t=40):
    ssh = shutil.which('ssh')
    if not ssh: return pk_exec(d.ip, u, p, cmd, t)
    if not re.fullmatch(r'[A-Za-z0-9_][A-Za-z0-9_.-]*', u or ''): raise Exception('اسم مستخدم غير صالح لـ SSH')
    import tempfile
    fd, ap = tempfile.mkstemp(prefix='qx', suffix='.sh')
    os.write(fd, f"#!{shutil.which('sh') or '/bin/sh'}\necho \"$QX_PW\"\n".encode())
    os.close(fd)
    os.chmod(ap, 0o700)
    env = dict(os.environ, QX_PW=p, SSH_ASKPASS=ap, SSH_ASKPASS_REQUIRE='force', DISPLAY=os.environ.get('DISPLAY') or ':0')
    try:
        r = subprocess.run([ssh, '-o', 'StrictHostKeyChecking=no', '-o', 'UserKnownHostsFile=/dev/null',
                            '-o', 'ConnectTimeout=8', '-o', 'NumberOfPasswordPrompts=1',
                            '-o', 'PreferredAuthentications=password,keyboard-interactive',
                            f'{u}@{d.ip}', cmd], capture_output=True, text=True, timeout=t, env=env, stdin=subprocess.DEVNULL)
    finally:
        try: os.remove(ap)
        except OSError: pass
    if r.returncode: raise Exception(f'ssh رجّع {r.returncode}: ' + r.stderr.strip()[-120:])
    return r.stdout


def parse_uci(txt):
    vals = {}
    for ln in txt.splitlines():
        ln = ln.strip()
        m = re.match(r"wireless\.([\w-]+)=(\S+)$", ln)
        if m:
            vals.setdefault(m.group(1), {})['.type'] = m.group(2).strip("'")
            continue
        m = re.match(r"wireless\.([\w-]+)\.(\w+)='?(.*?)'?$", ln)
        if m: vals.setdefault(m.group(1), {})[m.group(2)] = m.group(3)
    return vals


def pick_radio(vals):
    c = []
    for sec, o in vals.items():
        if not isinstance(o, dict) or o.get('.type') != 'wifi-device': continue
        ch = str(o.get('channel', ''))
        if str(o.get('band', '')) == '2g' or '11g' in str(o.get('hwmode', '')) or (ch.isdigit() and int(ch) <= 14):
            c.append((sec, ch))
    if len(c) != 1 or not re.fullmatch(r'[\w-]+', c[0][0]):
        raise Exception('تعذر تحديد راديو 2.4GHz بدقة (وجدت %d)' % len(c))
    return c[0]


def apply_uci(d, sid, log):
    try:
        ubus(d, sid, 'uci', 'apply', {'rollback': True, 'timeout': 30})
    except Exception as e:
        log.append(f'uci.apply: {e}')
        ubus(d, sid, 'uci', 'commit', {'config': 'wireless'})
        try:
            ubus(d, sid, 'file', 'exec', {'command': '/sbin/wifi', 'params': ['reload']})
        except Exception:
            return ' (حُفظت القناة لكن تعذرت إعادة تشغيل الواي فاي، أعد تشغيله من الأكسس)'
        return ''
    time.sleep(8)
    for _ in range(4):
        try:
            ubus(d, sid, 'uci', 'confirm', {})
            return ''
        except Exception:
            time.sleep(4)
    return ' (طُبّق التغيير لكن لم أستطع تأكيده، فإن فقد الأكسس الاتصال سيعود للقناة القديمة بعد 30 ثانية)'


def set_channel(q):
    log = []
    ip = str(q.get('ip', '')).strip()
    if not re.fullmatch(r'\d{1,3}(\.\d{1,3}){3}', ip): raise Fail('أدخل عنوان IP صالحاً', log)
    ipaddress.IPv4Address(ip)
    try: ch = int(q.get('channel'))
    except Exception: raise Fail('قناة غير صالحة', log)
    if not 1 <= ch <= 11: raise Fail('القناة يجب أن تكون من 1 إلى 11', log)
    u, p = q.get('user', ''), q.get('pw', '')
    d = Dev(ip)
    try: k = kind(d.connect())
    except Exception as e: raise Fail(str(e), log)
    if k != 'openwrt': raise Fail('تغيير القناة مدعوم لأجهزة OpenWrt فقط حالياً', log)
    for name, fn in (('الجلسة المباشرة', direct_sid), ('جلسة LuCI', luci_sid)):
        try:
            sid = fn(d, u, p)
            radio, old = pick_radio(ubus(d, sid, 'uci', 'get', {'config': 'wireless'}).get('values', {}))
            ubus(d, sid, 'uci', 'set', {'config': 'wireless', 'section': radio, 'values': {'channel': str(ch)}})
            try:
                note = apply_uci(d, sid, log)
            except Exception:
                try:
                    ubus(d, sid, 'uci', 'revert', {'config': 'wireless'})
                    log.append('↩ تم التراجع عن التغيير المؤقت')
                except Exception:
                    log.append('⚠ تعذر التراجع عن التغيير المؤقت: افتح LuCI واضغط Revert عند Unsaved changes')
                raise
            log.append(f'✓ {name}')
            return {'message': f'تم تغيير القناة على {radio} من {old} إلى {ch}' + note, 'log': log}
        except Exception as e:
            log.append(f'✗ {name}: {e}')
    try:
        radio, old = pick_radio(parse_uci(ssh_run(d, u, p, 'uci show wireless')))
        ssh_run(d, u, p, f'uci set wireless.{radio}.channel={ch} && uci commit wireless && (wifi reload >/dev/null 2>&1 &)')
        log.append('✓ SSH')
        return {'message': f'تم تغيير القناة على {radio} من {old} إلى {ch}', 'log': log}
    except Exception as e:
        log.append(f'✗ SSH: {e}')
    raise Fail('فشل تغيير القناة بكل الطرق. راجع السجل', log)


DEVF = os.path.join(os.environ['ZWIFI_DATA'], 'devices.json') if os.environ.get('ZWIFI_DATA') else os.path.expanduser('~/.qanvex_devices.json')
IPRX = r'\d{1,3}(\.\d{1,3}){3}'


def devs_load():
    try:
        with open(DEVF, encoding='utf-8') as f: l = json.load(f)
        return [d for d in l if isinstance(d, dict) and re.fullmatch(IPRX, str(d.get('ip', '')))]
    except Exception:
        return []


def devs_op(q):
    l, ip = devs_load(), str(q.get('ip', '')).strip()
    if q.get('op') == 'del':
        l = [d for d in l if d['ip'] != ip]
    elif q.get('op') == 'save':
        try: ipaddress.IPv4Address(ip)
        except ValueError: return l
        old = next((d for d in l if d['ip'] == ip), {})
        loc = str(q['loc'] if 'loc' in q else old.get('loc', '')).strip()[:60]
        l = [{'ip': ip, 'user': str(q.get('user', ''))[:32], 'name': str(q.get('name') or old.get('name', ''))[:40], 'loc': loc}] + [d for d in l if d['ip'] != ip]
    try:
        with open(DEVF, 'w', encoding='utf-8') as f: json.dump(l[:50], f, ensure_ascii=False)
    except OSError:
        pass
    return l[:50]


